import sys

INF = 10**18

def solve_case(a):
    n = len(a)
    a = [0] + a

    dp0 = [INF] * (n + 1)
    dp1 = [INF] * (n + 1)

    dp0[0] = 0
    dp0[1] = 1

    if n >= 2:
        dp0[2] = 1 + (a[1] != a[2])
        dp1[2] = 2 + (a[1] != a[2])

    for i in range(3, n + 1):
        dp0[i] = min(
            dp0[i - 1] + (a[i - 1] != a[i]),
            dp1[i - 1] + (a[i - 2] != a[i]),
        )

        dp1[i] = 1 + min(
            dp0[i - 2] + (a[i - 2] != a[i]) + (a[i - 1] != a[i]),
            dp1[i - 2] + (a[i - 3] != a[i]) + (a[i - 1] != a[i]),
        )

    return min(dp0[n], dp1[n])

def main():
